CREATE TYPE "public"."sv_scan_status" AS ENUM ('PENDING', 'COMPLETED', 'FAILED');
CREATE TYPE "public"."sv_finding_status" AS ENUM ('OPEN', 'ACCEPTED', 'DISMISSED');
CREATE TYPE "public"."sv_payment_status" AS ENUM ('PENDING', 'SUCCEEDED', 'FAILED', 'CANCELLED');
CREATE TABLE "sv_public_scans" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "project_id" uuid REFERENCES "sv_projects"("id"), "website" text NOT NULL, "status" "sv_scan_status" DEFAULT 'PENDING' NOT NULL, "result" jsonb, "created_at" timestamptz DEFAULT now() NOT NULL, "completed_at" timestamptz);
CREATE TABLE "sv_payments" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "order_id" uuid NOT NULL REFERENCES "sv_orders"("id"), "provider" text DEFAULT 'test' NOT NULL, "provider_event_id" text NOT NULL, "status" "sv_payment_status" DEFAULT 'PENDING' NOT NULL, "amount" numeric(12,2) NOT NULL, "currency" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "sv_payments_provider_event_unique" ON "sv_payments" ("provider", "provider_event_id");
CREATE TABLE "sv_findings" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "cycle_id" uuid NOT NULL REFERENCES "sv_cycles"("id"), "severity" text NOT NULL, "category" text NOT NULL, "title" text NOT NULL, "detail" text NOT NULL, "status" "sv_finding_status" DEFAULT 'OPEN' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "sv_recommendations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "organization_id" text NOT NULL REFERENCES "organization"("id"), "cycle_id" uuid NOT NULL REFERENCES "sv_cycles"("id"), "finding_id" uuid REFERENCES "sv_findings"("id"), "priority" text NOT NULL, "title" text NOT NULL, "action" text NOT NULL, "rationale" text NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL);
CREATE INDEX "sv_public_scans_project_idx" ON "sv_public_scans" ("project_id"); CREATE INDEX "sv_public_scans_created_idx" ON "sv_public_scans" ("created_at"); CREATE INDEX "sv_payments_org_idx" ON "sv_payments" ("organization_id"); CREATE INDEX "sv_findings_cycle_idx" ON "sv_findings" ("cycle_id"); CREATE INDEX "sv_findings_org_idx" ON "sv_findings" ("organization_id"); CREATE INDEX "sv_recommendations_cycle_idx" ON "sv_recommendations" ("cycle_id"); CREATE INDEX "sv_recommendations_org_idx" ON "sv_recommendations" ("organization_id");
ALTER TABLE "sv_public_scans" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_payments" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_findings" ENABLE ROW LEVEL SECURITY; ALTER TABLE "sv_recommendations" ENABLE ROW LEVEL SECURITY;
